sys_script_include.script:
var TISCAuthUtils = Class.create();
TISCAuthUtils.prototype = {
    initialize: function() {},

    getApiKey: function() {

        try {

            var gr = new GlideRecord('x_1893179_tisc_i_0_api_credentials');
            gr.addQuery('active', true);
            gr.query();

            if (gr.next()) {
                return gr.api_key.getDecryptedValue().toString();
            }

            gs.error('[TISCAuthUtils] No active API credential found');

            return '';

        } catch (ex) {

            gs.error(
                '[TISCAuthUtils] Error fetching API key: ' +
                ex.message
            );

            return '';
        }
    },

    type: 'TISCAuthUtils'
};
